import {demoProducts,demoStores,demoUsers,demoMovements,demoAudit,series,roleNames,roleDescriptions} from './data.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const root=$('#app');
const clone=x=>JSON.parse(JSON.stringify(x));
function stored(key,fallback){try{return JSON.parse(sessionStorage.getItem(key))||clone(fallback)}catch{return clone(fallback)}}
const state={demo:false,token:'',user:null,challenge:null,products:stored('ts-products',demoProducts),users:stored('ts-users',demoUsers),movements:stored('ts-movements',demoMovements),audit:stored('ts-audit',demoAudit),period:7,filters:{q:'',category:'',store:'',status:''},page:1,viewProducts:[],loading:false};
let timer,renderId=0,returnFocus=null;
const initials=n=>String(n).trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const avatar=n=>`<span class="avatar">${esc(initials(n))}</span>`;
