const roles={admin:['/dashboard','/products','/inventory','/movements','/stores','/users','/reports','/audit','/settings','/profile'],manager:['/dashboard','/products','/inventory','/movements','/stores','/reports','/profile'],employee:['/dashboard','/products','/inventory','/movements','/profile'],auditor:['/dashboard','/products','/inventory','/movements','/stores','/reports','/audit','/profile']};
const labels={'/dashboard':'Dashboard','/products':'Productos','/inventory':'Inventario','/movements':'Movimientos','/stores':'Tiendas','/users':'Usuarios','/reports':'Reportes','/audit':'Auditoría','/settings':'Configuración','/profile':'Mi perfil'};
const routeIcons={'/dashboard':'chart','/products':'box','/inventory':'box','/movements':'arrow','/stores':'store','/users':'users','/reports':'chart','/audit':'shield','/settings':'shield','/profile':'users'};
function saveDemo(){sessionStorage.setItem('ts-products',JSON.stringify(state.products));sessionStorage.setItem('ts-users',JSON.stringify(state.users));sessionStorage.setItem('ts-movements',JSON.stringify(state.movements));sessionStorage.setItem('ts-audit',JSON.stringify(state.audit));}
function startDemo(role=sessionStorage.getItem('ts-role')||'admin') {state.demo=true;state.user={...demoUsers[0],role,store:role==='employee'?'Surco':'Miraflores'};sessionStorage.setItem('ts-demo','1');sessionStorage.setItem('ts-role',role);}
async function api(path,method='GET',data){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);try{const response=await fetch(path,{method,headers:{'Content-Type':'application/json',Authorization:'Bearer '+state.token},body:data===undefined?undefined:JSON.stringify(data),signal:controller.signal});const result=await response.json();if(!response.ok)throw new Error(result.error||'No se pudo completar la operación.');return result;}catch(e){throw new Error(e.name==='AbortError'?'La conexión tardó demasiado. Intenta otra vez.':e.message)}finally{clearTimeout(timeout)}}
function toast(text,error=false){$('#toast-region').innerHTML=`<div class="toast ${error?'error':''}" role="status">${icon(error?'shield':'check')}<span>${esc(text)}</span><button aria-label="Cerrar aviso">×</button></div>`;$('#toast-region button').onclick=()=>$('#toast-region').replaceChildren();setTimeout(()=>$('#toast-region').replaceChildren(),5000);}
function navigate(path){closeModal();history.pushState({},'',path);state.filters={q:'',category:'',store:'',status:''};state.page=1;render();window.scrollTo(0,0);}
window.addEventListener('popstate',()=>render());
document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||e.defaultPrevented||e.ctrlKey||e.metaKey||e.shiftKey||a.target||a.download)return;const url=new URL(a.href,location.origin);if(url.origin===location.origin&&url.pathname!=='/'&&!url.pathname.startsWith('/auth/google')&&!url.pathname.startsWith('/auth/github')&&(labels[url.pathname]||['/login','/register','/auth/mfa'].includes(url.pathname)||/^\/products\/\d+$/.test(url.pathname))){e.preventDefault();navigate(url.pathname+url.search+url.hash)}});
function closeModal(){const exists=$('#modal-root').hasChildNodes();$('#modal-root').replaceChildren();document.body.style.overflow='';if(exists&&returnFocus?.isConnected)returnFocus.focus();}
function modal(title,body,footer='',compact=false){returnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${compact?'compact':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-btn" data-close aria-label="Cerrar">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}</section></div>`;document.body.style.overflow='hidden';$$('[data-close]').forEach(b=>b.onclick=closeModal);$('.modal-overlay').onclick=e=>{if(e.target===e.currentTarget)closeModal()};setTimeout(()=>$('.modal input, .modal select, .modal button')?.focus(),20);}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('.dropdown')?.remove();$('.notification-popover')?.remove();$('.workspace')?.classList.remove('drawer-open')}if(e.key==='Tab'&&$('.modal')){const list=$$('.modal button,.modal input,.modal select,.modal textarea,.modal a[href]').filter(x=>!x.disabled&&x.offsetParent!==null);if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0]?.focus()}}});
function field(name,label,type='text',placeholder='',value='',extra=''){return `<div class="field"><label for="${name}">${label}</label><div class="${type==='password'?'input-wrap':''}"><input class="input" id="${name}" name="${name}" type="${type}" placeholder="${placeholder}" value="${esc(value)}" ${extra}>${type==='password'?`<button class="icon-btn show-password" type="button" data-input="${name}" aria-label="Mostrar contraseña"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></button>`:''}</div><span class="field-error" id="${name}-error"></span></div>`;}
function selectField(name,label,options,value=''){return `<div class="field"><label for="${name}">${label}</label><select class="select" id="${name}" name="${name}">${options.map(x=>`<option value="${esc(typeof x==='string'?x:x[0])}" ${(typeof x==='string'?x:x[0])===value?'selected':''}>${esc(typeof x==='string'?x:x[1])}</option>`).join('')}</select></div>`;}
function bindPasswords(){$$('.show-password').forEach(b=>b.onclick=()=>{const input=document.getElementById(b.dataset.input);input.type=input.type==='password'?'text':'password';b.setAttribute('aria-label',input.type==='password'?'Mostrar contraseña':'Ocultar contraseña');});}
const googleIcon='<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path fill="#4285f4" d="M21 12.2c0-.6 0-1.3-.2-1.9H12v3.6h5.1a4.4 4.4 0 0 1-1.9 2.9v2.4h3.1c1.8-1.7 2.7-4 2.7-7Z"/><path fill="#34a853" d="M12 21c2.4 0 4.5-.8 6.1-2.3L15 16.3c-.8.6-1.8.9-3 .9-2.3 0-4.2-1.5-4.9-3.5H3.9v2.5A9.2 9.2 0 0 0 12 21Z"/><path fill="#fbbc05" d="M7.1 13.7a5.5 5.5 0 0 1 0-3.4V7.8H3.9a9 9 0 0 0 0 8.4Z"/><path fill="#ea4335" d="M12 6.8c1.3 0 2.5.5 3.4 1.3l2.6-2.6A8.7 8.7 0 0 0 12 3a9.2 9.2 0 0 0-8.1 4.8l3.2 2.5c.7-2 2.6-3.5 4.9-3.5Z"/></svg>';
const githubIcon='<svg class="icon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2a10 10 0 0 0-3.2 19.5c.5.1.7-.2.7-.5v-1.9c-2.8.6-3.4-1.2-3.4-1.2-.4-1.1-1.1-1.4-1.1-1.4-.9-.6.1-.6.1-.6 1 0 1.5 1 1.5 1 .9 1.5 2.4 1.1 3 .8.1-.6.4-1.1.7-1.4-2.3-.3-4.6-1.1-4.6-5a3.9 3.9 0 0 1 1-2.7 3.6 3.6 0 0 1 .1-2.7s.8-.3 2.8 1a9.7 9.7 0 0 1 5 0c1.9-1.3 2.7-1 2.7-1 .6 1.4.2 2.4.1 2.7a3.9 3.9 0 0 1 1 2.7c0 3.9-2.3 4.7-4.6 5 .4.4.7 1 .7 1.9V21c0 .3.2.6.7.5A10 10 0 0 0 12 2Z"/></svg>';
function authPreview(){return `<div class="panel" style="padding:22px"><div class="flex between"><h3 style="font-size:13px">Inventario general</h3><span class="badge green">En orden</span></div><div style="display:flex;gap:35px;margin:20px 0"><div><p style="font-size:9px">Stock total</p><b style="font-size:27px;letter-spacing:-.06em">12,480</b></div><div><p style="font-size:9px">Tiendas</p><b style="font-size:27px">4</b></div></div>${demoProducts.slice(0,3).map(p=>`<div class="preview-row" style="font-size:9px;padding:12px 0"><span>${p.name}</span><span class="badge ${p.stock<=p.min?'amber':'green'}" style="font-size:8px">${status(p)}</span></div>`).join('')}<p class="demo-caption">Vista ilustrativa del producto</p></div>`;}
function authView(register=false){clearInterval(timer);root.innerHTML=`<main id="main" class="auth-layout"><aside class="auth-brand-panel">${brand()}<div class="auth-brand-content"><div class="eyebrow">Tu equipo. Tus tiendas. Tu control.</div><h2>Gestiona tu inventario<br>con mayor claridad.</h2><p>Todo lo que necesitas para organizar productos y tomar mejores decisiones, en un solo espacio.</p><div class="auth-preview">${authPreview()}</div><div class="auth-benefits">${['Inventario centralizado','Acceso por roles','Seguridad MFA'].map(x=>`<span>${icon('check')}${x}</span>`).join('')}</div></div><div class="auth-brand-footer">TechStore — Proyecto académico.</div></aside><section class="auth-form-panel"><a class="auth-back" href="/">Volver al inicio ${icon('arrow')}</a><div class="auth-form ${register?'register':''}"><div class="mobile-brand">${brand()}</div><h1>${register?'Crea tu cuenta':'Bienvenido de nuevo'}</h1><p>${register?'Empieza a organizar tu inventario con TechStore.':'Ingresa tus credenciales para continuar.'}</p><form id="auth-form" novalidate><div class="form-error" id="form-error" role="alert"></div>${register?field('name','Nombre completo','text','Tu nombre y apellido','','required autocomplete="name"'):''}${field('email','Correo electrónico','email','nombre@empresa.com',register?'':localStorage.getItem('ts-email')||'','required autocomplete="username"')}${field('password','Contraseña','password',register?'Crea una contraseña segura':'Tu contraseña','','required autocomplete="'+(register?'new-password':'current-password')+'"')}${register?`<div class="password-checks"><b>Requisitos de contraseña</b><div class="password-rules">${[['length','8 caracteres mínimo'],['uppercase','Una mayúscula'],['number','Un número'],['special','Un carácter especial']].map(x=>`<span class="password-rule" data-rule="${x[0]}"><i class="dot"></i>${x[1]}</span>`).join('')}</div></div><div style="height:13px"></div>${field('confirm','Confirmar contraseña','password','Repite tu contraseña','','required autocomplete="new-password"')}${selectField('store','Tienda asignada',['Lima','Arequipa'])}`:`<div class="auth-options"><label class="check-label"><input type="checkbox" id="remember" ${localStorage.getItem('ts-email')?'checked':''}>Recordar mi correo</label><button type="button" id="forgot">¿Olvidaste tu contraseña?</button></div>`}<button class="btn primary full" id="auth-submit" type="submit">${register?'Crear cuenta':'Iniciar sesión'} ${icon('arrow')}</button></form>${register?'':`<div class="auth-divider">o continúa con</div><div class="social-buttons"><button class="btn secondary" data-provider="google">${googleIcon}Google</button><button class="btn secondary" data-provider="github">${githubIcon}GitHub</button></div>`}<div class="auth-foot">${register?'¿Ya tienes una cuenta? <a href="/login">Iniciar sesión</a>':'¿No tienes una cuenta? <a href="/register">Crear cuenta</a>'}</div><div class="auth-demo-link">¿Quieres conocer el producto?<br><a href="/dashboard?demo=1">Explorar la demo sin registrarte ${icon('arrow')}</a></div></div></section></main>`;
bindPasswords();
if(register){$('#password').oninput=()=>{const p=$('#password').value,checks={length:p.length>=8,uppercase:/[A-Z]/.test(p),number:/\d/.test(p),special:/[^A-Za-z0-9]/.test(p)};$$('[data-rule]').forEach(x=>{x.classList.toggle('met',checks[x.dataset.rule]);x.firstElementChild.outerHTML=checks[x.dataset.rule]?icon('check'):'<i class="dot"></i>';});};}
else {$('#forgot').onclick=()=>modal('Recuperar acceso','<p>Para recuperar el acceso a este proyecto, contacta al administrador de TechStore. El servicio de recuperación por correo aún no está configurado.</p><p>No compartas tu contraseña ni la clave de tu autenticador.</p>',`<button class="btn primary" data-close>Entendido</button>`,true);$$('[data-provider]').forEach(b=>b.onclick=async()=>{const provider=b.dataset.provider;try{const response=await fetch('/auth/'+provider,{redirect:'manual'});if(response.status===503){const r=await response.json();toast(r.error,true)}else location.href='/auth/'+provider}catch{location.href='/auth/'+provider}});}
$('#auth-form').onsubmit=async e=>{e.preventDefault();$$('.field-error').forEach(x=>x.textContent='');$$('.input.invalid').forEach(x=>x.classList.remove('invalid'));$('#form-error').textContent='';let valid=true;const err=(id,text)=>{$('#'+id+'-error').textContent=text;$('#'+id).classList.add('invalid');valid=false;};const d=Object.fromEntries(new FormData(e.target));if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.email))err('email','Ingresa un correo electrónico válido.');if(!d.password)err('password','Ingresa tu contraseña.');if(register){if(!d.name.trim())err('name','Ingresa tu nombre completo.');if(d.password.length<8||!/[A-Z]/.test(d.password)||!/\d/.test(d.password)||!/[^A-Za-z0-9]/.test(d.password))err('password','Completa todos los requisitos de contraseña.');if(d.confirm!==d.password)err('confirm','Las contraseñas no coinciden.');}if(!valid){$('.input.invalid')?.focus();return;}const btn=$('#auth-submit');btn.disabled=true;btn.textContent=register?'Creando cuenta…':'Verificando…';try{if(register){await api('/api/register','POST',{name:d.name,email:d.email,password:d.password,store:d.store});navigate('/login');toast('Cuenta creada. Inicia sesión para configurar MFA.');}else{if($('#remember').checked)localStorage.setItem('ts-email',d.email);else localStorage.removeItem('ts-email');state.challenge=await api('/api/login','POST',{email:d.email,password:d.password});state.challenge.expires=Date.now()+300000;state.demo=false;sessionStorage.removeItem('ts-demo');navigate('/auth/mfa');}}catch(e){$('#form-error').textContent=e.message;btn.disabled=false;btn.innerHTML=(register?'Crear cuenta':'Iniciar sesión')+' '+icon('arrow');}};
}
function mfaView(){clearInterval(timer);const preview=new URLSearchParams(location.search).has('demo');if(preview&&!state.challenge)state.challenge={demo:true,expires:Date.now()+300000};const c=state.challenge;root.innerHTML=`<main class="mfa-page" id="main">${brand()}<section class="mfa-card"><div class="security-shield">${icon('shield')}</div><h1>Verifica tu identidad</h1><p>${c?'Ingresa el código de seis dígitos de tu aplicación Authenticator para acceder a TechStore.':'Inicia sesión para obtener un desafío de verificación seguro.'}</p>${c?`${c.demo?'<div class="badge">Vista de demostración · Código: 381274</div>':''}${c.secret?`<div class="setup-secret"><strong>Configura tu autenticador</strong><p>Agrega una cuenta con esta clave y guárdala en un lugar seguro.</p><code>${esc(c.secret)}</code><a href="${esc(c.uri)}">Abrir Authenticator</a></div>`:''}<form id="mfa-form"><div class="form-error" id="mfa-error" role="alert"></div><div class="otp-inputs">${Array.from({length:6},(_,i)=>`<input class="otp-input" name="digit${i}" aria-label="Dígito ${i+1}" inputmode="numeric" pattern="[0-9]" maxlength="1" autocomplete="${i===0?'one-time-code':'off'}">`).join('')}</div><div class="countdown">El desafío vence en <b id="countdown">05:00</b></div><button class="btn primary full" id="mfa-submit">Verificar código ${icon('arrow')}</button></form><div class="mfa-resend">¿Venció el desafío? <button id="new-challenge">Iniciar otra vez</button></div>`:`<a class="btn primary full" href="/login">Ir a iniciar sesión</a>`}</section><a class="text-link" href="/login">Volver al inicio de sesión</a><p class="demo-caption">Tu código cambia cada 30 segundos. No lo compartas.</p></main>`;
if(!c)return;const inputs=$$('.otp-input');inputs.forEach((x,i)=>{x.oninput=()=>{x.value=x.value.replace(/\D/g,'').slice(-1);x.classList.toggle('filled',!!x.value);if(x.value)inputs[i+1]?.focus();$('#mfa-error').textContent='';$('.otp-inputs').classList.remove('incorrect');};x.onkeydown=e=>{if(e.key==='Backspace'&&!x.value)inputs[i-1]?.focus();if(e.key==='ArrowLeft')inputs[i-1]?.focus();if(e.key==='ArrowRight')inputs[i+1]?.focus();};x.onpaste=e=>{e.preventDefault();const code=e.clipboardData.getData('text').replace(/\D/g,'').slice(0,6);code.split('').forEach((v,j)=>{if(inputs[j]){inputs[j].value=v;inputs[j].classList.add('filled')}});inputs[Math.min(code.length,5)].focus();};});inputs[0].focus();const tick=()=>{const n=Math.max(0,Math.ceil((c.expires-Date.now())/1000));$('#countdown').textContent=String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');if(n===0){clearInterval(timer);$('#mfa-error').textContent='El desafío ha vencido. Inicia sesión otra vez.';$('#mfa-submit').disabled=true;}};tick();timer=setInterval(tick,1000);$('#new-challenge').onclick=()=>{state.challenge=null;navigate('/login')};$('#mfa-form').onsubmit=async e=>{e.preventDefault();const code=inputs.map(x=>x.value).join('');if(code.length!==6){$('#mfa-error').textContent='Completa los seis dígitos.';inputs.find(x=>!x.value)?.focus();return;}const b=$('#mfa-submit');b.disabled=true;b.textContent='Verificando…';try{if(c.demo){if(code!=='381274')throw Error('Código incorrecto. Prueba con 381274.');startDemo();}else{const result=await api('/api/mfa','POST',{challenge:c.challenge,code});state.token=result.token;state.user=result.user;state.demo=false;}state.challenge=null;clearInterval(timer);navigate('/dashboard');toast('Identidad verificada. Bienvenido a TechStore.');}catch(e){$('#mfa-error').textContent=e.message;$('.otp-inputs').classList.add('incorrect');b.disabled=false;b.textContent='Verificar código';}};
}
export async function render(){const id=++renderId;clearInterval(timer);const path=location.pathname;document.title=(labels[path]||({'/login':'Iniciar sesión','/register':'Crear cuenta','/auth/mfa':'Verificación de identidad'}[path])||'TechStore')+' · TechStore';if(location.hash.startsWith('#mfa=')){try{state.challenge=JSON.parse(atob(location.hash.slice(5).replaceAll('-','+').replaceAll('_','/')));state.challenge.expires=Date.now()+300000;state.demo=false;sessionStorage.removeItem('ts-demo');history.replaceState({},'','/auth/mfa');mfaView();return;}catch{toast('No se pudo recuperar la verificación.',true)}}if(path==='/'){landing();return;}if(path==='/login'){authView();return;}if(path==='/register'){authView(true);return;}if(path==='/auth/mfa'){mfaView();return;}if(new URLSearchParams(location.search).has('demo'))startDemo();else if(!state.user&&sessionStorage.getItem('ts-demo'))startDemo();if(!state.user){history.replaceState({},'','/login');authView();return;}const permissionPath=path.startsWith('/products/')?'/products':path;if(!roles[state.user.role]?.includes(permissionPath)){root.innerHTML=`<main class="container section" id="main">${brand()}<div class="empty-state"><div class="empty-icon">${icon('shield')}</div><h1>Este acceso está reservado</h1><p>Tu rol no tiene permisos para esta sección.</p><a class="btn primary" href="/dashboard">Volver al dashboard</a></div></main>`;return;}shell(path);try{if(state.demo)state.viewProducts=state.products.filter(p=>state.user.role==='manager'?p.store===state.user.store:true);else {$('#screen').innerHTML=skeleton();state.viewProducts=(await api('/api/products')).map(p=>({...p,sku:'TS-'+String(p.id).padStart(5,'0'),category:'General',brand:'Sin especificar',min:5,type:'box',description:'',...p}));}if(id!==renderId)return;await renderScreen(path);bindShell();}catch(e){if(id===renderId){$('#screen').innerHTML=empty('No pudimos cargar la información.',e.message,`<button class="btn primary" id="retry">Reintentar</button>`);$('#retry').onclick=()=>render();bindShell();}}}
function skeleton(){return `<div class="page-head"><div class="skeleton" style="height:30px;width:220px"></div></div><div class="stats-grid">${'<div class="skeleton skeleton-stat"></div>'.repeat(4)}</div><div class="dashboard-grid"><div class="skeleton skeleton-panel"></div><div class="skeleton skeleton-panel"></div></div>`;}
function empty(title,text,action=''){return `<div class="empty-state"><div class="empty-icon">${icon('box')}</div><h3>${esc(title)}</h3><p>${esc(text)}</p>${action}</div>`;}
function shell(path){const active=path.startsWith('/products/')?'/products':path;root.innerHTML=`<div class="workspace"><div class="drawer-backdrop" id="drawer-backdrop"></div><aside class="sidebar">${brand()}<button class="icon-btn drawer-close" id="drawer-close" aria-label="Cerrar menú">×</button><div class="sidebar-caption">Espacio de trabajo</div><nav class="side-nav">${roles[state.user.role].filter(p=>p!=='/profile'&&p!=='/settings').map(p=>`<a class="side-link ${p===active?'active':''}" ${p===active?'aria-current="page"':''} href="${p}">${icon(routeIcons[p])}${labels[p]}</a>`).join('')}</nav><div class="sidebar-bottom">${state.user.role==='admin'?`<a class="side-link ${active==='/settings'?'active':''}" href="/settings">${icon('shield')}Configuración</a>`:''}<div class="sidebar-help"><strong>${state.demo?'Explora con libertad':'Tu inventario, conectado'}</strong><p>${state.demo?'Esta demo usa datos ficticios. Tus cambios se guardan solo en esta pestaña.':'Cada operación está protegida por tus permisos de acceso.'}</p><a href="/">Conocer TechStore ${icon('arrow')}</a></div><a class="sidebar-profile" href="/profile">${avatar(state.user.name)}<span><strong>${esc(state.user.name)}</strong><small>${roleNames[state.user.role]}</small></span></a><button class="side-link" id="logout" style="border:0;background:none;width:100%">${icon('arrow')}${state.demo?'Salir de la demo':'Cerrar sesión'}</button></div></aside><div class="workspace-main"><header class="topbar"><div class="flex"><button class="icon-btn mobile-toggle" id="drawer-toggle" aria-label="Abrir navegación" aria-expanded="false">${icon('menu')}</button><div class="breadcrumb"><span>Espacio de trabajo</span>${icon('arrow')}<strong>${labels[active]||'Detalle del producto'}</strong></div></div><div class="top-actions"><form class="global-search" id="global-search">${icon('box')}<input name="q" placeholder="Buscar productos…" aria-label="Buscar productos"><kbd>/</kbd></form><button class="icon-btn notification-button" id="notifications" aria-label="Notificaciones">${icon('shield')}</button><a href="/profile" aria-label="Mi perfil">${avatar(state.user.name)}</a></div></header>${state.demo?`<div class="demo-banner"><span><strong>Modo demostración</strong> · Datos ficticios</span><div class="demo-role"><label for="demo-role">Explorar como</label><select id="demo-role">${Object.entries(roleNames).map(([id,n])=>`<option value="${id}" ${state.user.role===id?'selected':''}>${n}</option>`).join('')}</select></div></div>`:''}<main id="main" class="workspace-content"><div id="screen"></div></main></div></div>`;}
function bindShell(){const toggle=open=>{$('.workspace').classList.toggle('drawer-open',open);$('#drawer-toggle').setAttribute('aria-expanded',open);if(open)$('#drawer-close').focus();else $('#drawer-toggle').focus()};$('#drawer-toggle').onclick=()=>toggle(true);$('#drawer-close').onclick=()=>toggle(false);$('#drawer-backdrop').onclick=()=>toggle(false);$('#logout').onclick=()=>{state.token='';state.user=null;state.demo=false;state.challenge=null;sessionStorage.removeItem('ts-demo');navigate('/login')};if(state.demo)$('#demo-role').onchange=e=>{startDemo(e.target.value);if(!roles[state.user.role].includes(location.pathname))navigate('/dashboard');else render();};$('#global-search').onsubmit=e=>{e.preventDefault();const q=new FormData(e.target).get('q');navigate('/products');state.filters.q=q;renderScreen('/products')};$('#notifications').onclick=()=>{if($('.notification-popover')){$('.notification-popover').remove();return;}const low=state.viewProducts.filter(p=>p.stock<=p.min);const div=document.createElement('div');div.className='notification-popover';div.innerHTML=`<h3>Notificaciones</h3>${low.length?`<a class="notification-item" href="/inventory"><strong>${low.length} productos necesitan atención</strong><p>Consulta el stock bajo y planifica la reposición.</p></a>`:'<p class="note">Todo está en orden. No hay alertas de stock.</p>'}${state.demo?'<a class="notification-item" href="/movements"><strong>Recepción de mercadería</strong><p>24 unidades añadidas en San Isidro · Demo</p></a>':''}`;$('.top-actions').append(div);};}
function pageHead(title,text,actions=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(text)}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`;}
function stats(items){return `<div class="stats-grid">${items.map(([label,value,ic,note,tone=''])=>`<div class="stat-card"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon ${tone}">${icon(ic)}</span></div><div class="stat-number ${String(value).startsWith('S/')?'currency':''}">${value}</div><div class="stat-foot">${note}</div></div>`).join('')}</div>`;}
function totals(rows=state.viewProducts){return {stock:rows.reduce((n,p)=>n+p.stock,0),low:rows.filter(p=>p.stock>0&&p.stock<=p.min).length,out:rows.filter(p=>p.stock===0).length,value:rows.reduce((n,p)=>n+p.stock*p.price,0),stores:new Set(rows.map(p=>p.store)).size};}
// Las siguientes vistas comparten catálogo, filtros y componentes.
async function renderScreen(path){
 $('#notifications')?.classList.toggle('hidden',localStorage.getItem('ts-notifications')==='off');
 if(path==='/dashboard')return dashboard();
 if(path==='/products'||path==='/inventory')return catalog(path==='/inventory');
 if(/^\/products\/\d+$/.test(path))return detail(Number(path.split('/').at(-1)));
 if(path==='/users')return usersView();
 if(path==='/reports')return reportsView();
 if(path==='/movements'||path==='/audit')return logView(path);
 if(path==='/stores')return storesView();
 if(path==='/profile')return profileView();
 if(path==='/settings')return settingsView();
}
function movementChart(){if(!state.demo)return `<div class="empty-state" style="padding:35px 15px"><div class="empty-icon">${icon('chart')}</div><h3>Aún no hay historial disponible</h3><p>El inventario actual está conectado. El historial de movimientos se puede explorar en la demo.</p><a class="text-link" href="/dashboard?demo=1">Explorar demo ${icon('arrow')}</a></div>`;const d=series[state.period];const pts=a=>a.map((n,i)=>`${45+i*(470/(a.length-1))},${165-n*1.6}`).join(' ');return `<svg class="chart-svg" viewBox="0 0 550 200" role="img" aria-label="Movimientos de inventario de demostración, periodo de ${state.period} días">${[0,20,40,60,80].map(n=>`<path d="M45 ${165-n*1.6}H530" class="grid-line"/><text x="7" y="${169-n*1.6}">${n}</text>`).join('')}<polygon points="45,165 ${pts(d.incoming)} 515,165" fill="#245bd708"/><polyline points="${pts(d.incoming)}" class="line-blue"/><polyline points="${pts(d.outgoing)}" class="line-cyan"/>${d.labels.map((l,i)=>`<text x="${45+i*470/(d.labels.length-1)}" y="192" text-anchor="middle">${l}</text>`).join('')}</svg><div class="chart-legend"><span><i class="legend-dot"></i>Entradas</span><span><i class="legend-dot cyan"></i>Salidas</span><span>Datos ilustrativos</span></div>`;}
function periods(){return `<div class="segmented">${[7,30,90].map(n=>`<button data-period="${n}" class="${state.period===n?'active':''}">${n} días</button>`).join('')}</div>`;}
function bindPeriods(fn){$$('[data-period]').forEach(b=>b.onclick=()=>{state.period=Number(b.dataset.period);fn()});}
function categoryChart(rows=state.viewProducts){const colors=['#245bd7','#6897e5','#75c5d2','#b1c9ef','#d9e3f2','#8ea9bc'];const map={};rows.forEach(p=>map[p.category]=(map[p.category]||0)+p.stock);const entries=Object.entries(map),total=entries.reduce((n,[,v])=>n+v,0);let end=0;const stops=entries.map(([,n],i)=>{const start=end;end+=total?n/total*100:100/entries.length;return `${colors[i%colors.length]} ${start}% ${end}%`;});return `<div class="donut-layout"><div class="donut" style="background:${stops.length?'conic-gradient('+stops.join(',')+')':'#edf1f7'}"><div class="donut-label"><b>${total}</b><small>unidades</small></div></div><div class="donut-legend">${entries.map(([name,n],i)=>`<div class="donut-item"><i style="background:${colors[i%colors.length]}"></i><span>${esc(name)}</span><b>${n}</b></div>`).join('')||'<span class="note">Sin stock registrado</span>'}</div></div>`;}
function lowStock(){const low=state.viewProducts.filter(p=>p.stock<=p.min);return low.map(p=>`<a class="low-row" href="/products/${p.id}"><div class="product-image ${p.type}">${icon(p.type)}</div><div class="product-info"><strong>${esc(p.name)}</strong><small>${esc(p.store)}</small></div><span class="badge ${p.stock?'amber':'red'}">${p.stock} unidades</span></a>`).join('')||'<p class="note">Todos los productos tienen stock suficiente.</p>';}
function activity(){if(!state.demo)return '<p class="note">El registro de actividad histórica está disponible en la demo.</p>';return visibleMovements().slice(0,4).map(m=>`<div class="activity-row">${avatar(m.user)}<div><strong>${esc(m.user)}</strong><p>${esc(m.type)} · ${m.quantity} unidades · ${esc(state.products.find(p=>p.id===m.product)?.name||'Producto')}</p></div><time>${new Date(m.date).toLocaleTimeString('es-PE',{hour:'2-digit',minute:'2-digit'})}</time></div>`).join('')||'<p class="note">No hay movimientos para esta tienda.</p>';}
function visibleMovements(){return state.movements.filter(m=>['manager','employee'].includes(state.user.role)?m.store===state.user.store:true);}
function dashboard(){const t=totals(),hour=new Date().getHours(),greeting=hour<12?'Buenos días':hour<19?'Buenas tardes':'Buenas noches';$('#screen').innerHTML=pageHead(`${greeting}, ${state.user.name.split(' ')[0]}`,'Aquí tienes un resumen del inventario de TechStore.',`<a class="btn secondary" href="/inventory">Ver inventario ${icon('arrow')}</a>${['admin','manager'].includes(state.user.role)?`<button class="btn primary" id="new-product">+ Nuevo producto</button>`:''}`)+stats([['Productos activos',state.viewProducts.length,'box','Referencias en el catálogo'],['Stock total',t.stock,'box','Unidades disponibles','green'],['Stock bajo',t.low,'shield','Productos para reponer','amber'],['Tiendas',t.stores,'store','Ubicaciones con productos','gray']])+`<div class="dashboard-grid"><section class="panel"><div class="panel-title"><div><h3>Movimientos de inventario</h3><p>${state.demo?'Una visión de las entradas y salidas · Demo':'Seguimiento de tus operaciones'}</p></div>${state.demo?periods():''}</div>${movementChart()}</section><section class="panel"><div class="panel-title"><div><h3>Stock por categoría</h3><p>Distribución del inventario actual</p></div>${icon('chart')}</div>${categoryChart()}</section></div><div class="dashboard-grid"><section class="panel"><div class="panel-title"><div><h3>Productos con stock bajo</h3><p>Prioriza tu próxima reposición</p></div><a class="text-link" href="/inventory">Ver todos ${icon('arrow')}</a></div>${lowStock()}</section><section class="panel"><div class="panel-title"><div><h3>Actividad reciente</h3><p>${state.demo?'Movimientos de demostración':'Tu operación diaria'}</p></div><a class="text-link" href="/movements">Ver más</a></div>${activity()}</section></div>`;$('#new-product')?.addEventListener('click',()=>productModal());bindPeriods(dashboard);}
function filterBar(extra=''){const categories=[...new Set(state.viewProducts.map(p=>p.category))],stores=[...new Set(state.viewProducts.map(p=>p.store))];return `<div class="filter-bar"><div class="search-input">${icon('box')}<input id="catalog-search" placeholder="Buscar por producto o SKU…" aria-label="Buscar por producto o SKU" value="${esc(state.filters.q)}"></div><button class="btn secondary small filter-toggle" id="filter-toggle">Filtros ${icon('menu')}</button><div class="filter-group"><select class="select" id="filter-category" aria-label="Filtrar categoría"><option value="">Todas las categorías</option>${categories.map(c=>`<option ${c===state.filters.category?'selected':''}>${esc(c)}</option>`).join('')}</select><select class="select" id="filter-store" aria-label="Filtrar tienda"><option value="">Todas las tiendas</option>${stores.map(s=>`<option ${s===state.filters.store?'selected':''}>${esc(s)}</option>`).join('')}</select><select class="select" id="filter-status" aria-label="Filtrar estado"><option value="">Todos los estados</option>${['Disponible','Stock bajo','Agotado'].map(s=>`<option ${s===state.filters.status?'selected':''}>${s}</option>`).join('')}</select>${extra}</div></div>`;}
function filteredProducts(){const f=state.filters;return state.viewProducts.filter(p=>(!f.q||(p.name+' '+p.sku).toLowerCase().includes(f.q.toLowerCase()))&&(!f.category||p.category===f.category)&&(!f.store||p.store===f.store)&&(!f.status||status(p)===f.status));}
function bindFilters(update){$('#catalog-search').oninput=e=>{state.filters.q=e.target.value;state.page=1;update()};['category','store','status'].forEach(key=>$('#filter-'+key).onchange=e=>{state.filters[key]=e.target.value;state.page=1;update()});$('#filter-toggle').onclick=()=>{$('.filter-group').classList.toggle('open');$('#filter-toggle').setAttribute('aria-expanded',$('.filter-group').classList.contains('open'))};}
function table(headers,rows){return `<div class="table-panel responsive-table"><div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div></div>`;}
function td(label,html,cls=''){return `<td data-label="${label}" class="${cls}">${html}</td>`;}
function productCell(p){return `<a class="product-cell product-link" href="/products/${p.id}"><div class="product-image ${p.type}">${icon(p.type)}</div><div><strong>${esc(p.name)}</strong><small>${esc(p.brand)}</small></div></a>`;}
function canEdit(p){return state.user.role==='admin'||state.user.role==='manager'&&p.store===state.user.store;}
function canStock(p){return canEdit(p)||state.user.role==='employee'&&p.store===state.user.store;}
function catalog(inventory=false){const t=totals();$('#screen').innerHTML=pageHead(inventory?'Inventario':'Productos',inventory?'Controla las unidades disponibles y organiza tu próxima reposición.':'Administra el catálogo de productos de TechStore.',`${state.user.role!=='employee'?`<button class="btn secondary" id="export">${icon('chart')}Exportar</button>`:''}${!inventory&&['admin','manager'].includes(state.user.role)?'<button class="btn primary" id="new-product">+ Nuevo producto</button>':''}`)+(inventory?stats([['Stock total',t.stock,'box','Unidades disponibles'],['Stock bajo',t.low,'shield','Referencias para reponer','amber'],['Sin stock',t.out,'box','Referencias agotadas','gray'],['Valor del inventario',money(t.value),'chart','Precio × unidades actuales','green']]):'')+filterBar()+`<div id="catalog-results"></div>`;const update=()=>catalogRows(inventory);update();bindFilters(update);$('#export')?.addEventListener('click',()=>exportProducts(filteredProducts()));$('#new-product')?.addEventListener('click',()=>productModal());}
function catalogRows(inventory){const rows=filteredProducts(),pageSize=6,pages=Math.max(1,Math.ceil(rows.length/pageSize));state.page=Math.min(state.page,pages);if(!rows.length){$('#catalog-results').innerHTML=`<div class="panel">${empty('No encontramos productos.','Prueba cambiando los filtros o agrega un nuevo producto.','<button class="btn secondary" id="reset-filters">Limpiar filtros</button>')}</div>`;$('#reset-filters').onclick=()=>{state.filters={q:'',category:'',store:'',status:''};catalog(inventory)};return;}const shown=rows.slice((state.page-1)*pageSize,state.page*pageSize),headers=inventory?['Producto','Tienda','Stock actual','Stock mínimo','Estado','Acciones']:['Producto','SKU','Categoría','Tienda','Stock','Precio','Estado','Acciones'];const html=shown.map(p=>`<tr>${td('Producto',productCell(p))}${!inventory?td('SKU',esc(p.sku),'mono')+td('Categoría',esc(p.category)):''}${td('Tienda',esc(p.store))}${td(inventory?'Stock actual':'Stock',`<strong>${p.stock}</strong> <span class="muted">uds.</span>`)}${inventory?td('Stock mínimo',p.min):td('Precio',money(p.price))}${td('Estado',badge(p))}${td('Acciones',inventory&&canStock(p)?`<button class="btn secondary small" data-stock="${p.id}">Ajustar stock</button>`:`<button class="icon-btn" data-menu="${p.id}" aria-label="Acciones de ${esc(p.name)}">···</button>`,'row-actions')}</tr>`).join('');$('#catalog-results').innerHTML=table(headers,html)+`<div class="table-footer"><span>Mostrando ${(state.page-1)*pageSize+1}–${Math.min(state.page*pageSize,rows.length)} de ${rows.length} productos</span><div class="pagination"><button data-page="${state.page-1}" ${state.page===1?'disabled':''} aria-label="Página anterior">‹</button>${Array.from({length:pages},(_,i)=>`<button data-page="${i+1}" class="${state.page===i+1?'active':''}" aria-label="Página ${i+1}">${i+1}</button>`).join('')}<button data-page="${state.page+1}" ${state.page===pages?'disabled':''} aria-label="Página siguiente">›</button></div></div>`;$$('[data-page]').forEach(b=>b.onclick=()=>{state.page=Number(b.dataset.page);catalogRows(inventory)});$$('[data-stock]').forEach(b=>b.onclick=()=>stockModal(state.viewProducts.find(p=>p.id===Number(b.dataset.stock))));$$('[data-menu]').forEach(b=>b.onclick=e=>productMenu(e.currentTarget,state.viewProducts.find(p=>p.id===Number(b.dataset.menu))));}
function record(action,resource){state.audit.unshift({id:Date.now(),date:new Date().toISOString(),user:state.user.name,action,resource,result:'Correcto'});}
function productMenu(button,p){$('.dropdown')?.remove();const d=document.createElement('div');d.className='dropdown';d.innerHTML=`<a href="/products/${p.id}">${icon('box')}Ver detalle</a>${canEdit(p)?'<button data-edit>'+icon('box')+'Editar producto</button>':''}${canStock(p)?'<button data-adjust>'+icon('arrow')+'Ajustar stock</button>':''}${canEdit(p)?'<button class="danger" data-delete>Eliminar producto</button>':''}`;document.body.append(d);const r=button.getBoundingClientRect();d.style.left=Math.max(10,Math.min(innerWidth-170,r.right-160))+'px';d.style.top=Math.min(innerHeight-d.offsetHeight-10,r.bottom+5)+'px';d.querySelector('[data-edit]')?.addEventListener('click',()=>{d.remove();productModal(p)});d.querySelector('[data-adjust]')?.addEventListener('click',()=>{d.remove();stockModal(p)});d.querySelector('[data-delete]')?.addEventListener('click',()=>{d.remove();deleteModal(p)});setTimeout(()=>{const outside=e=>{if(!d.contains(e.target)){d.remove();document.removeEventListener('click',outside)}};document.addEventListener('click',outside)},0);d.querySelector('a')?.focus();}
function productModal(p=null){if(p&&!canEdit(p)||!['admin','manager'].includes(state.user.role))return;const stores=state.demo?demoStores.map(s=>s.name):['Lima','Arequipa'];const categories=['Laptops','Smartphones','Accesorios','Monitores','Audio','Tablets','General'];const editable=state.demo?'':'disabled';modal(p?'Editar producto':'Nuevo producto',`<form id="product-form"><div class="form-error" id="product-error" role="alert"></div><div class="form-grid">${field('product-name','Nombre del producto','text','Ej. MacBook Air M3',p?.name||'','required maxlength="100"')}${field('product-sku','SKU','text','Ej. TS-LAP-001',p?.sku||'',editable)}${field('product-brand','Marca','text','Ej. Apple',p?.brand||'',editable)}${selectField('product-category','Categoría',categories,p?.category||'Laptops')}${field('product-price','Precio (S/)','number','0.00',p?.price??'','required min="0" step="0.01"')}${selectField('product-store','Tienda',state.user.role==='manager'?[state.user.store]:stores,p?.store||state.user.store)}${field('product-stock','Stock inicial','number','0',p?.stock??0,'required min="0" step="1"')}${field('product-min','Stock mínimo','number','5',p?.min??5,'min="0" step="1" '+editable)}<div class="field span-two"><label for="product-description">Descripción</label><textarea class="input" id="product-description" name="product-description" placeholder="Características principales del producto" ${editable}>${esc(p?.description||'')}</textarea></div></div>${!state.demo?'<p class="note">El catálogo conectado guarda nombre, tienda, precio y stock. Los campos descriptivos estarán disponibles cuando se amplíe el catálogo.</p>':''}</form>`,`<button class="btn secondary" data-close>Cancelar</button><button class="btn primary" type="submit" form="product-form" id="save-product">Guardar producto</button>`);if(!state.demo)$('#product-category').disabled=true;
$('#product-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));const price=Number(f['product-price']),stock=Number(f['product-stock']),min=Number(f['product-min']??5),name=f['product-name'].trim();if(!name||!Number.isFinite(price)||price<0||!Number.isInteger(stock)||stock<0||!Number.isInteger(min)||min<0){$('#product-error').textContent='Revisa el nombre, el precio y las cantidades.';return;}if(state.demo&&(!f['product-sku'].trim()||state.products.some(x=>x.sku===f['product-sku'].trim()&&x.id!==p?.id))){$('#product-error').textContent='Ingresa un SKU único.';$('#product-sku').focus();return;}const b=$('#save-product');b.disabled=true;b.textContent='Guardando…';try{const data={name,price,stock,store:f['product-store']};if(state.demo){const d={...data,id:p?.id||Math.max(0,...state.products.map(x=>x.id))+1,sku:f['product-sku'].trim(),brand:f['product-brand'].trim()||'Sin especificar',category:f['product-category'],min,description:f['product-description'],type:({Laptops:'laptop',Smartphones:'phone',Monitores:'monitor',Audio:'headphones',Tablets:'tablet',Accesorios:'mouse'})[f['product-category']]||'box'};if(p)state.products[state.products.findIndex(x=>x.id===p.id)]=d;else state.products.push(d);record(p?'UPDATE_PRODUCT':'CREATE_PRODUCT',name);saveDemo();}else await api(p?'/api/products/'+p.id:'/api/products',p?'PATCH':'POST',data);closeModal();await render();toast(p?'Producto actualizado correctamente.':'Producto creado correctamente.');}catch(e){$('#product-error').textContent=e.message;b.disabled=false;b.textContent='Guardar producto';}};
}
function stockModal(p){if(!canStock(p))return;let type='Entrada';modal('Ajustar stock',`<div class="stock-summary"><div class="product-image ${p.type}">${icon(p.type)}</div><div><h3>${esc(p.name)}</h3><p>${esc(p.store)} · Stock actual: <strong>${p.stock} unidades</strong></p></div></div><form id="stock-form"><div class="form-error" id="stock-error" role="alert"></div><div class="segmented">${['Entrada','Salida','Ajuste'].map((x,i)=>`<button type="button" data-type="${x}" class="${i===0?'active':''}">${x}</button>`).join('')}</div>${field('quantity','Cantidad','number','0','','required min="0" step="1"')}${field('reason','Motivo','text','Ej. Reposición de proveedor','','required maxlength="150"')}<div class="stock-preview"><span>Stock después del cambio</span><strong id="stock-preview">${p.stock} uds.</strong></div><p class="note" style="margin-top:12px">Un ajuste establece la cantidad total. Una entrada suma unidades y una salida las resta.</p></form>`,`<button class="btn secondary" data-close>Cancelar</button><button class="btn primary" form="stock-form" id="confirm-stock">Confirmar cambio</button>`,true);const result=()=>type==='Ajuste'?Number($('#quantity').value):p.stock+(type==='Entrada'?1:-1)*Number($('#quantity').value);const preview=()=>$('#stock-preview').textContent=result()+' uds.';$('#quantity').oninput=preview;$$('[data-type]').forEach(b=>b.onclick=()=>{type=b.dataset.type;$$('[data-type]').forEach(x=>x.classList.toggle('active',x===b));preview()});$('#stock-form').onsubmit=async e=>{e.preventDefault();const qty=Number($('#quantity').value),stock=result(),reason=$('#reason').value.trim();if(!reason||!Number.isInteger(qty)||qty<0||!Number.isInteger(stock)||stock<0){$('#stock-error').textContent='Ingresa un motivo y una cantidad válida. El stock no puede ser negativo.';return;}const b=$('#confirm-stock');b.disabled=true;b.textContent='Actualizando…';try{if(state.demo){state.products.find(x=>x.id===p.id).stock=stock;state.movements.unshift({id:Date.now(),product:p.id,type,quantity:qty,store:p.store,reason,user:state.user.name,date:new Date().toISOString()});record('STOCK_ADJUSTMENT',p.name);saveDemo();}else await api('/api/products/'+p.id,'PATCH',{stock});closeModal();await render();toast('Stock actualizado correctamente.');}catch(e){$('#stock-error').textContent=e.message;b.disabled=false;b.textContent='Confirmar cambio';}};}
function deleteModal(p){modal('Eliminar producto',`<p>¿Quieres eliminar <strong>${esc(p.name)}</strong> del catálogo? Esta acción elimina su referencia de inventario.</p><div class="form-error" id="delete-error"></div>`,`<button class="btn secondary" data-close>Cancelar</button><button class="btn danger" id="confirm-delete">Eliminar producto</button>`,true);$('#confirm-delete').onclick=async()=>{const b=$('#confirm-delete');b.disabled=true;try{if(state.demo){state.products=state.products.filter(x=>x.id!==p.id);record('DELETE_PRODUCT',p.name);saveDemo();}else await api('/api/products/'+p.id,'DELETE');closeModal();if(location.pathname==='/products/'+p.id)navigate('/products');else await render();toast('Producto eliminado del catálogo.');}catch(e){$('#delete-error').textContent=e.message;b.disabled=false;}};}
function csvDownload(name,headers,rows){const q=x=>'"'+String(x??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"';const content=[headers,...rows].map(r=>r.map(q).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Reporte exportado correctamente.');}
function exportProducts(rows){csvDownload('techstore-inventario'+(state.demo?'-demo':'')+'.csv',['Producto','SKU','Categoría','Tienda','Stock','Precio (S/)','Estado'],rows.map(p=>[p.name,p.sku,p.category,p.store,p.stock,p.price,status(p)]));}
function detail(id){const p=state.viewProducts.find(p=>p.id===id);if(!p){$('#screen').innerHTML=empty('Producto no disponible.','El producto no existe o no corresponde a tu tienda.','<a class="btn primary" href="/products">Volver al catálogo</a>');return;}const moves=state.demo?visibleMovements().filter(m=>m.product===id):[];$('#screen').innerHTML=pageHead(p.name,'Ficha de producto e inventario por ubicación.',`<a class="btn secondary" href="/products">Volver</a>${canStock(p)?'<button class="btn secondary" id="adjust-product">Ajustar stock</button>':''}${canEdit(p)?'<button class="btn primary" id="edit-product">Editar producto</button>':''}`)+`<div class="detail-grid"><section class="panel"><div class="detail-visual">${icon(p.type)}</div>${badge(p)}<div class="detail-price">${money(p.price)}</div><p class="detail-desc">${esc(p.description||'Consulta el precio y la disponibilidad actual de este producto.')}</p><div class="detail-meta"><div><small>SKU</small><b>${esc(p.sku)}</b></div><div><small>Marca</small><b>${esc(p.brand)}</b></div><div><small>Categoría</small><b>${esc(p.category)}</b></div><div><small>Stock mínimo</small><b>${p.min} unidades</b></div></div></section><div><section class="panel"><div class="panel-title"><div><h3>Inventario por tienda</h3><p>Disponibilidad actual del producto</p></div>${icon('store')}</div><div class="detail-stock-row"><span>${esc(p.store)}</span><span><strong>${p.stock}</strong> unidades</span></div></section><section class="panel"><div class="panel-title"><div><h3>Historial de movimientos</h3><p>${state.demo?'Registro de demostración':'Seguimiento de las operaciones'}</p></div>${icon('arrow')}</div>${moves.length?moves.map(m=>`<div class="activity-row"><div class="stat-icon">${icon('arrow')}</div><div><strong>${esc(m.type)} · ${m.quantity} unidades</strong><p>${esc(m.reason)} · ${esc(m.user)}</p></div><time>${date(m.date)}</time></div>`).join(''):'<p class="note">No hay movimientos registrados para mostrar.</p>'}</section></div></div>`;$('#edit-product')?.addEventListener('click',()=>productModal(p));$('#adjust-product')?.addEventListener('click',()=>stockModal(p));}
async function usersView(){if(!state.demo){$('#screen').innerHTML=skeleton();state.users=(await api('/api/users')).map(u=>({...u,status:'Activo',last:'No disponible'}));}$('#screen').innerHTML=pageHead('Usuarios','Gestiona los roles y las tiendas asignadas a tu equipo.')+`<div class="filter-bar"><div class="search-input">${icon('users')}<input id="user-search" placeholder="Buscar por nombre o email…" aria-label="Buscar usuarios"></div><select class="select" id="user-role" aria-label="Filtrar rol"><option value="">Todos los roles</option>${Object.entries(roleNames).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><div id="user-results"></div>`;const update=()=>{const q=$('#user-search').value.toLowerCase(),role=$('#user-role').value;const rows=state.users.filter(u=>(u.name+' '+u.email).toLowerCase().includes(q)&&(!role||u.role===role));$('#user-results').innerHTML=rows.length?table(['Usuario','Email','Rol','Tienda','Estado','Último acceso','Acciones'],rows.map(u=>`<tr>${td('Usuario',`<div class="product-cell">${avatar(u.name)}<strong>${esc(u.name)}</strong></div>`)}${td('Email',esc(u.email))}${td('Rol',`<span class="badge ${u.role==='admin'?'':'gray'}">${roleNames[u.role]}</span>`)}${td('Tienda',esc(u.store))}${td('Estado',state.demo?`<span class="badge ${u.status==='Activo'?'green':u.status==='Bloqueado'?'red':'amber'}">${u.status}</span>`:'<span class="muted">Sin información</span>')}${td('Último acceso',esc(u.last))}${td('Acciones',`<button class="icon-btn" data-edit-user="${u.id}" aria-label="Editar ${esc(u.name)}">···</button>`,'row-actions')}</tr>`).join('')):empty('No encontramos usuarios.','Prueba con otro nombre, email o rol.');$$('[data-edit-user]').forEach(b=>b.onclick=()=>userModal(state.users.find(u=>u.id===Number(b.dataset.editUser))));};update();$('#user-search').oninput=update;$('#user-role').onchange=update;}
function userModal(u){modal('Editar acceso del usuario',`<div class="stock-summary">${avatar(u.name)}<div><h3>${esc(u.name)}</h3><p>${esc(u.email)}</p></div></div><form id="user-form"><div class="form-error" id="user-error"></div>${selectField('user-edit-role','Rol',Object.entries(roleNames),u.role)}${selectField('user-edit-store','Tienda asignada',state.demo?demoStores.map(s=>s.name):['Lima','Arequipa'],u.store)}<p class="note">Los permisos se aplicarán de acuerdo con el rol seleccionado.</p></form>`,`<button class="btn secondary" data-close>Cancelar</button><button class="btn primary" form="user-form" id="save-user">Guardar cambios</button>`,true);$('#user-form').onsubmit=async e=>{e.preventDefault();const role=$('#user-edit-role').value,store=$('#user-edit-store').value,b=$('#save-user');b.disabled=true;try{if(state.demo){if(u.role==='admin'&&role!=='admin'&&state.users.filter(x=>x.role==='admin').length===1)throw Error('Debe quedar al menos un administrador.');Object.assign(state.users.find(x=>x.id===u.id),{role,store});record('UPDATE_USER',u.name);saveDemo();}else{await api('/api/users','PATCH',{id:u.id,role,store});state.user=await api('/api/me');}closeModal();if(state.user.role!=='admin')navigate('/dashboard');else await render();toast('Permisos actualizados correctamente.');}catch(e){$('#user-error').textContent=e.message;b.disabled=false;}};}
function reportsView(){const rows=filteredProducts(),t=totals(rows);$('#screen').innerHTML=pageHead('Reportes','Una visión clara del valor y la distribución de tu inventario.','<button class="btn secondary" id="export-report">'+icon('chart')+'Exportar reporte</button>')+filterBar(state.demo?`<select class="select" id="report-period" aria-label="Periodo de movimientos">${[7,30,90].map(n=>`<option value="${n}" ${n===state.period?'selected':''}>Últimos ${n} días</option>`).join('')}</select>`:'')+`<div id="report-content"></div>`;const update=()=>{const items=filteredProducts(),tot=totals(items),stores=[...new Set(items.map(p=>p.store))];$('#report-content').innerHTML=stats([['Valor del inventario',money(tot.value),'chart','Valorización del stock actual','green'],['Productos',items.length,'box','Referencias filtradas'],['Stock crítico',tot.low+tot.out,'shield','Bajo o agotado','amber'],['Movimientos',state.demo?visibleMovements().filter(m=>(!state.filters.store||m.store===state.filters.store)&&items.some(p=>p.id===m.product)).length:'—','arrow',state.demo?'Registros de demostración':'Historial aún no disponible','gray']])+`<div class="dashboard-grid"><section class="panel"><div class="panel-title"><div><h3>Movimientos por periodo</h3><p>${state.demo?'Tendencia ilustrativa del periodo seleccionado':'Seguimiento de entradas y salidas'}</p></div>${state.demo?periods():''}</div>${movementChart()}</section><section class="panel"><div class="panel-title"><div><h3>Inventario por categoría</h3><p>Stock de las referencias filtradas</p></div>${icon('box')}</div>${categoryChart(items)}</section></div><section class="panel"><div class="panel-title"><div><h3>Stock por tienda</h3><p>Distribución de las unidades disponibles</p></div>${icon('store')}</div>${stores.length?stores.map(s=>{const n=items.filter(p=>p.store===s).reduce((n,p)=>n+p.stock,0);return `<div class="bar-row" style="grid-template-columns:110px 1fr 50px"><span>${esc(s)}</span><div class="bar-track"><div class="bar-fill" style="width:${tot.stock?n/tot.stock*100:0}%"></div></div><b>${n} uds.</b></div>`;}).join(''):'<p class="note">No hay productos que coincidan con los filtros.</p>'}</section><p class="note" style="margin-top:16px">Los valores de inventario corresponden a una fotografía del stock actual.</p>`;bindPeriods(()=>{update();if($('#report-period'))$('#report-period').value=state.period;});};update();bindFilters(update);$('#report-period')?.addEventListener('change',e=>{state.period=Number(e.target.value);update()});$('#export-report').onclick=()=>exportProducts(filteredProducts());}
const actionNames={LOGIN_SUCCESS:'Inicio de sesión',STOCK_ADJUSTMENT:'Ajuste de stock',UPDATE_PRODUCT:'Producto actualizado',CREATE_PRODUCT:'Producto creado',DELETE_PRODUCT:'Producto eliminado',UPDATE_USER:'Usuario actualizado',USER_BLOCKED:'Usuario bloqueado'};
function logView(path){const audit=path==='/audit';$('#screen').innerHTML=pageHead(audit?'Auditoría':'Movimientos',audit?'Consulta las acciones y los accesos registrados en la plataforma.':'Sigue las entradas, salidas y ajustes de tu inventario.',state.demo?'<button class="btn secondary" id="export-log">'+icon('chart')+'Exportar</button>':'');if(!state.demo){$('#screen').innerHTML+=`<section class="panel">${empty('El historial aún no está disponible.','Puedes explorar una muestra completa de movimientos y auditoría en el modo demostración.','<a class="btn primary" href="'+path+'?demo=1">Explorar demo</a>')}</section>`;return;}$('#screen').innerHTML+=`<div class="filter-bar"><div class="search-input">${icon('box')}<input id="log-search" placeholder="Buscar usuario, producto o acción…" aria-label="Buscar registros"></div><select class="select" id="log-type" aria-label="Filtrar acción"><option value="">Todas las acciones</option>${(audit?Object.entries(actionNames):[['Entrada','Entrada'],['Salida','Salida'],['Ajuste','Ajuste']]).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><input class="select" type="date" id="log-date" aria-label="Filtrar fecha"></div><div id="log-results"></div>`;let filtered=[];const update=()=>{const q=$('#log-search').value.toLowerCase(),type=$('#log-type').value,day=$('#log-date').value;const data=audit?state.audit:visibleMovements();filtered=data.filter(x=>(!type||(audit?x.action:x.type)===type)&&(!day||x.date.slice(0,10)===day)&&JSON.stringify(x).toLowerCase().includes(q));const headers=audit?['Fecha','Usuario','Acción','Recurso','Resultado']:['Fecha','Producto','Tipo','Cantidad','Tienda','Responsable'];const rows=filtered.map(m=>`<tr>${td('Fecha',date(m.date))}${audit?td('Usuario',`<div class="product-cell">${avatar(m.user)}${esc(m.user)}</div>`)+td('Acción',`<span class="badge gray">${actionNames[m.action]||esc(m.action)}</span><small class="mono" style="display:block;margin-top:5px">${esc(m.action)}</small>`)+td('Recurso',esc(m.resource))+td('Resultado',`<span class="badge ${m.result==='Bloqueado'?'red':'green'}">${m.result}</span>`):td('Producto',esc(state.products.find(p=>p.id===m.product)?.name||'Producto eliminado'))+td('Tipo',`<span class="badge ${m.type==='Entrada'?'green':m.type==='Salida'?'amber':''}">${m.type}</span>`)+td('Cantidad',m.quantity+' uds.')+td('Tienda',esc(m.store))+td('Responsable',esc(m.user))}</tr>`).join('');$('#log-results').innerHTML=filtered.length?table(headers,rows):`<section class="panel">${empty('No encontramos registros.','Prueba cambiando la acción, la fecha o la búsqueda.')}</section>`;};update();$('#log-search').oninput=update;$('#log-type').onchange=update;$('#log-date').onchange=update;$('#export-log').onclick=()=>csvDownload(audit?'techstore-auditoria-demo.csv':'techstore-movimientos-demo.csv',audit?['Fecha','Usuario','Acción','Recurso','Resultado']:['Fecha','Producto','Tipo','Cantidad','Tienda','Responsable'],filtered.map(m=>audit?[m.date,m.user,m.action,m.resource,m.result]:[m.date,state.products.find(p=>p.id===m.product)?.name||'Producto eliminado',m.type,m.quantity,m.store,m.user]));}
function storesView(){const names=[...new Set(state.viewProducts.map(p=>p.store))];const stores=state.demo?demoStores.filter(s=>state.user.role==='manager'?s.name===state.user.store:true):names.map((name,i)=>({id:i,name,address:'Ubicación asignada al catálogo',manager:'No especificado'}));$('#screen').innerHTML=pageHead('Tiendas','Todas tus ubicaciones, conectadas a una misma visión.')+`<div class="stores-grid">${stores.map(s=>{const rows=state.viewProducts.filter(p=>p.store===s.name),t=totals(rows);return `<section class="panel store-card"><div class="store-head"><div class="store-icon">${icon('store')}</div><div><h3>${esc(s.name)}</h3><p>${esc(s.address)}</p></div><span class="badge green" style="margin-left:auto">Activa</span></div><div class="store-stats"><div><small>Productos</small><b>${rows.length}</b></div><div><small>Stock total</small><b>${t.stock}</b></div><div><small>Stock crítico</small><b>${t.low+t.out}</b></div></div><div class="store-footer"><span>${state.demo?'Gerente: '+esc(s.manager):'Vista del inventario actual'}</span><button class="text-link" data-store="${esc(s.name)}" style="border:0;background:none;padding:0">Ver productos ${icon('arrow')}</button></div></section>`;}).join('')||empty('No hay tiendas disponibles.','Agrega productos para empezar a visualizar su inventario.')}</div>`;$$('[data-store]').forEach(b=>b.onclick=()=>{navigate('/products');state.filters.store=b.dataset.store;catalog()});}
function profileView(){const u=state.user;$('#screen').innerHTML=pageHead('Mi perfil','Tu información personal y la seguridad de tu cuenta.')+`<div class="profile-grid"><section class="panel profile-card"><div class="avatar big">${esc(initials(u.name))}</div><h2>${esc(u.name)}</h2><p>${esc(u.email)}</p><span class="badge">${roleNames[u.role]}</span><div class="profile-info"><div class="info-row"><span>Tienda asignada</span><strong>${esc(u.store)}</strong></div><div class="info-row"><span>Tipo de sesión</span><strong>${state.demo?'Demostración':'Autenticada'}</strong></div><div class="info-row"><span>Acceso</span><strong>${state.demo?'Datos de ejemplo':'MFA verificado'}</strong></div></div></section><div><section class="panel profile-security"><div class="panel-title"><div><h3>Seguridad</h3><p>Protege tu cuenta y cada acceso</p></div>${icon('shield')}</div><div class="security-line"><div><strong>Autenticación MFA</strong><p>Verificación mediante Authenticator</p></div><span class="badge ${state.demo?'':'green'}">${state.demo?'Ejemplo activo':'Verificado'}</span></div><div class="security-line"><div><strong>Contraseña</strong><p>Una contraseña segura protege tu acceso</p></div><button class="btn secondary small" id="change-password">Cambiar</button></div><div class="security-line"><div><strong>Sesión actual</strong><p>${state.demo?'Vista de demostración':esc(navigator.userAgent.includes('Windows')?'Navegador · Windows':'Navegador actual')}</p></div><button class="text-link" id="close-session" style="border:0;background:none">Cerrar sesión</button></div></section><section class="panel" style="margin-top:20px"><div class="panel-title"><h3>Últimos accesos</h3></div>${state.demo?`<div class="activity-row"><div class="stat-icon green">${icon('shield')}</div><div><strong>Chrome · Windows</strong><p>Sesión verificada con MFA · Datos demo</p></div><span class="badge green">Hoy, 10:42</span></div>`:'<p class="note">El historial de accesos aún no está disponible. Tu sesión actual fue verificada con MFA.</p>'}</section></div></div>`;$('#change-password').onclick=()=>modal('Cambiar contraseña',`<p>${state.demo?'Vista de demostración. Esta acción valida el formulario y no cambia credenciales reales.':'El cambio de contraseña aún no está habilitado en este proyecto. Contacta al administrador para recuperar o actualizar tus credenciales.'}</p>${state.demo?`<form id="password-form"><div class="form-error" id="password-error"></div>${field('new-password','Nueva contraseña','password','Mínimo 8 caracteres','','required')}${field('confirm-password','Confirmar contraseña','password','Repite la contraseña','','required')}</form>`:''}`,state.demo?'<button class="btn secondary" data-close>Cancelar</button><button class="btn primary" form="password-form">Validar cambio demo</button>':'<button class="btn primary" data-close>Entendido</button>',true);$('#change-password').addEventListener('click',()=>{bindPasswords();$('#password-form')?.addEventListener('submit',e=>{e.preventDefault();const p=$('#new-password').value;if(p.length<8||!/[A-Z]/.test(p)||!/\d/.test(p)||!/[^A-Za-z0-9]/.test(p)){ $('#password-error').textContent='Usa 8 caracteres, una mayúscula, un número y un carácter especial.';return;}if(p!==$('#confirm-password').value){$('#password-error').textContent='Las contraseñas no coinciden.';return;}closeModal();toast('Validación completada. Demo sin cambio de credenciales.');});});$('#close-session').onclick=()=>$('#logout').click();}
function settingsView(){const pref=localStorage.getItem('ts-notifications')!=='off';$('#screen').innerHTML=pageHead('Configuración','Personaliza tu experiencia de trabajo en TechStore.')+`<div class="settings-grid"><section class="panel"><div class="panel-title"><h3>Preferencias de interfaz</h3></div><div class="security-line"><div><strong>Mostrar alertas de inventario</strong><p class="note">Notificaciones de stock bajo en la barra superior.</p></div><button class="switch" id="notification-switch" role="switch" aria-label="Mostrar alertas de inventario" aria-checked="${pref}"></button></div><div class="security-line"><div><strong>Idioma</strong><p class="note">Español · Perú</p></div><span class="badge gray">Predeterminado</span></div><div class="security-line"><div><strong>Moneda</strong><p class="note">Precios y reportes en soles</p></div><strong>PEN · S/</strong></div></section><section class="panel"><div class="panel-title"><h3>${state.demo?'Espacio de demostración':'Acerca de TechStore'}</h3></div><p class="note">${state.demo?'Los cambios de la demo se guardan en esta pestaña. Puedes restablecer el catálogo, los usuarios y la actividad a sus datos originales.':'Proyecto académico para gestionar inventario con autenticación MFA y permisos por rol.'}</p>${state.demo?'<button class="btn secondary" id="reset-demo" style="margin-top:20px">Restablecer datos demo</button>':'<a class="text-link" href="/" style="margin-top:20px">Ver página principal</a>'}</section></div>`;$('#notification-switch').onclick=e=>{const b=e.currentTarget,on=b.getAttribute('aria-checked')!=='true';b.setAttribute('aria-checked',on);localStorage.setItem('ts-notifications',on?'on':'off');$('#notifications').classList.toggle('hidden',!on);toast('Preferencia guardada.');};$('#reset-demo')?.addEventListener('click',()=>{modal('Restablecer demostración','<p>Se restaurarán los productos, usuarios y movimientos ficticios de esta pestaña. Los datos reales del servidor no se modifican.</p>','<button class="btn secondary" data-close>Cancelar</button><button class="btn primary" id="confirm-reset">Restablecer demo</button>',true);$('#confirm-reset').onclick=()=>{state.products=clone(demoProducts);state.users=clone(demoUsers);state.movements=clone(demoMovements);state.audit=clone(demoAudit);saveDemo();closeModal();render();toast('Datos de demostración restablecidos.');};});}
